def clean(df):
    df = df.copy()
    # drop exact duplicate rows (and duplicated penguin_id rows)
    df = df.drop_duplicates()
    if 'penguin_id' in df.columns:
        df = df.drop_duplicates(subset=['penguin_id'], keep='first')
    # normalize label variants
    if 'island' in df.columns:
        df['island'] = df['island'].replace({'Dram': 'Dream', 'Torgerson': 'Torgersen'})
    if 'sex' in df.columns:
        df['sex'] = df['sex'].astype(str).str.strip().str.lower().replace({'nan': float('nan')})
    # ensure numeric columns are truly numeric
    for col in ['flipper_length_mm', 'body_mass_g', 'bill_length_mm', 'bill_depth_mm', 'year']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col].astype(str).str.replace(',', '', regex=False), errors='coerce')
    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['species', 'flipper_length_mm'])
    g = d.groupby('species')['flipper_length_mm'].mean()
    return {str(k): float(v) for k, v in g.items() if pd.notna(k)}
